using Microsoft.Extensions.Options;

var builder = WebApplication.CreateBuilder(args);
builder.Services.Configure<RecommendationOptions>(
    builder.Configuration.GetSection("Recommendations"));
builder.Services.AddSingleton<RecommendationService>();
var app = builder.Build();

app.MapGet("/recommendations", (RecommendationService service) =>
    service.IsEnabled ? Results.Ok(new[] { "book-42" }) : Results.NoContent());
app.Run();

public sealed class RecommendationService(IOptions<RecommendationOptions> options)
{
    // IOptions binds once: a reloaded file never reaches this property
    public bool IsEnabled => options.Value.Enabled;
}

using Microsoft.Extensions.Options;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddOptions<RecommendationOptions>()
    .BindConfiguration("Recommendations")
    .ValidateDataAnnotations()
    .ValidateOnStart(); // a bad value fails at startup, not on first use
builder.Services.AddSingleton<RecommendationService>();
var app = builder.Build();

app.MapGet("/recommendations", (RecommendationService service) =>
    service.IsEnabled ? Results.Ok(new[] { "book-42" }) : Results.NoContent());
app.Run();

public sealed class RecommendationService(
    IOptionsMonitor<RecommendationOptions> options)
{
    // CurrentValue is the latest bound value: read it on every call
    public bool IsEnabled => options.CurrentValue.Enabled;
}
